// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(uint64 _number, uint64 _timestamp) public {
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(
            _number,
            _timestamp,
            1,
            bytes32(uint256(2)),
            3,
            bytes32(uint256(4)),
            5,
            6
        );
        assertTrue(
            c.number() != c.timestamp() || _number == _timestamp,
            "number and timestamp may coincide only when their inputs coincide"
        );
    }
}
